const html = $input.first().json.data;

function parseEuro(str) {
  return parseFloat(str.replace(/\s|&nbsp;| /g, '').replace(',', '.'));
}

// Miroir JS de lib/product-matching.ts (extractModel) - garder synchronise
// manuellement, ce workflow n8n ne peut pas importer le code TypeScript du repo.
const CATEGORY_PREFIXES = {
  raquettes: ['Raquette de tennis '],
};

function escapeRegExp(value) {
  return value.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
}

function extractModel(title, brand, category) {
  let model = title;

  for (const prefix of CATEGORY_PREFIXES[category] || []) {
    if (model.toLowerCase().startsWith(prefix.toLowerCase())) {
      model = model.slice(prefix.length);
      break;
    }
  }

  const brandPattern = new RegExp(`\\b${escapeRegExp(brand)}\\b`, 'i');
  model = model.replace(brandPattern, '');

  model = model.replace(/\bnon\s+cord[ée]e?\b/gi, '');
  model = model.replace(/\bcord[ée]e?\b/gi, '');

  return model.replace(/\s+/g, ' ').trim();
}

const merchantId = '9bcb1729-926d-4462-b949-57f991e08673';
const category = 'raquettes';

const articles = html.match(/<article class="product-miniature[\s\S]*?<\/article>/g) || [];
const items = [];

for (const block of articles) {
  const urlMatch = block.match(/<a href="([^"]+)"[^>]*class="thumbnail product-thumbnail">/);
  const imgMatch = block.match(/data-full-size-image-url="([^"]+)"/) || block.match(/<img\s+src="([^"]+)"/);
  const titleMatch = block.match(/<h3 class="h3 product-title">\s*<a[^>]*>\s*([\s\S]*?)\s*<\/a>/);
  const priceMatch = block.match(/<span class="price" aria-label="Prix">\s*([\d.,\s ]+)\s*€\s*<\/span>/);
  const regularMatch = block.match(/<span class="regular-price" aria-label="Prix de base">\s*([\d.,\s ]+)\s*€\s*<\/span>/);
  const brandMatch = block.match(/alt="([^"]+)"\s+class="brand-logo"/);

  if (!urlMatch || !titleMatch || !priceMatch || !regularMatch || !brandMatch || !imgMatch) continue;

  const originalPrice = parseEuro(regularMatch[1]);
  const discountedPrice = parseEuro(priceMatch[1]);
  if (!(originalPrice > discountedPrice) || !(discountedPrice > 0)) continue;

  const discountPercentage = Math.round(((originalPrice - discountedPrice) / originalPrice) * 100);
  const title = titleMatch[1].replace(/\s+/g, ' ').trim();
  const brand = brandMatch[1].trim();

  items.push({
    json: {
      title,
      brand,
      category,
      image_url: imgMatch[1],
      original_price: originalPrice,
      discounted_price: discountedPrice,
      discount_percentage: discountPercentage,
      merchant_id: merchantId,
      affiliate_url: urlMatch[1],
      model: extractModel(title, brand, category),
    },
  });
}

return items;

const items = $input.all();
if (items.length === 0) {
  return [];
}
const affiliateUrls = items.map((i) => i.json.affiliate_url);
const merchantId = items[0].json.merchant_id;
return [{ json: { merchant_id: merchantId, affiliate_urls: affiliateUrls } }];
